# Makes synthetic_example.csv, the made-up data used in the worked example in this lesson.
# These data were generated by a random number generator. They are not from a real study.
set.seed(2026)
group <- rep(c("G1", "G2", "G3", "G4"), each = 20)
n <- length(group)
shift1 <- c(G1 = 0, G2 = 0, G3 = 3, G4 = 3)[group]
shift2 <- c(G1 = 0, G2 = 2, G3 = 0, G4 = 2)[group]
var01 <- 10 + shift1 + rnorm(n, sd = 1.5)
var02 <- 8 + shift2 + rnorm(n, sd = 1.5)
var03 <- 0.8 * var01 + rnorm(n, sd = 1)
noise <- sapply(4:10, function(i) rnorm(n, mean = 5, sd = 1.5))
colnames(noise) <- sprintf("var%02d", 4:10)
synth <- data.frame(group = group, var01 = var01, var02 = var02, var03 = var03, noise)
synth[-1] <- round(synth[-1], 2)
write.csv(synth, "synthetic_example.csv", row.names = FALSE)
